// === Tab: mySketch ===
let SHADER_PRIME, SHADER_A, SHADER_B, SHADER_C;
let prime, flectA, flectB, flectC;

function setup() {
	const dim = min(1112, 834);
	createCanvas(dim, dim);
	prime = createGraphics(width, height / 4, WEBGL);
	flectA = createGraphics(width, height / 4, WEBGL);
	flectB = createGraphics(width, height / 4, WEBGL);
	flectC = createGraphics(width, height / 4, WEBGL);
	SHADER_PRIME = prime.createShader(vert, frag);
	SHADER_A = flectA.createShader(vert, flectFrag);
	SHADER_B = flectB.createShader(vert, flectFrag);
	SHADER_C = flectC.createShader(vert, flectFrag);
	background(100);
}

function draw() {

	const pd = pixelDensity();
	SHADER_PRIME.setUniform('u_resolution', [prime.width * pd, prime.height * pd]);
	SHADER_A.setUniform('u_resolution', [prime.width * pd, prime.height * pd]);
	SHADER_B.setUniform('u_resolution', [prime.width * pd, prime.height * pd]);
	SHADER_C.setUniform('u_resolution', [prime.width * pd, prime.height * pd]);
	SHADER_PRIME.setUniform('u_time', frameCount / 30);
	SHADER_A.setUniform('u_tex', prime);
	SHADER_B.setUniform('u_tex', flectA);
	SHADER_C.setUniform('u_tex', flectB);
	SHADER_A.setUniform('u_noiseScale', 2);
	SHADER_B.setUniform('u_noiseScale', 4);
	SHADER_C.setUniform('u_noiseScale', 8);

	prime.shader(SHADER_PRIME);
	prime.quad(-1, -1, 1, -1, 1, 1, -1, 1);

	flectA.shader(SHADER_A);
	flectA.quad(-1, -1, 1, -1, 1, 1, -1, 1);

	flectB.shader(SHADER_B);
	flectB.quad(-1, -1, 1, -1, 1, 1, -1, 1);

	flectC.shader(SHADER_C);
	flectC.quad(-1, -1, 1, -1, 1, 1, -1, 1);

	image(prime, 0, 0);
	image(flectA, 0, height / 4);
	image(flectB, 0, (height / 4) * 2);
	image(flectC, 0, (height / 4) * 3);

}

