// === Tab: tab2 ===
const vert = `
	precision mediump float;
	attribute vec3 aPosition;

	uniform mat4 uModelViewMatrix;
	uniform mat4 uProjectionMatrix;

	void main() {
		vec4 positionVec4 = vec4(aPosition, 1.);
		gl_Position = positionVec4;
	}
`

const frag = `
	precision mediump float;

	float sdCircle( vec2 p, float r )
	{
    return length(p) - r;
	}

	float sdBox( in vec2 p, in vec2 b )
	{
    vec2 d = abs(p)-b;
    return length(max(d,0.0)) + min(max(d.x,d.y),0.0);
	}

	float sdEquilateralTriangle(  in vec2 p, in float r )
	{
    const float k = sqrt(3.0);
    p.x = abs(p.x) - r;
    p.y = p.y + r/k;
    if( p.x+k*p.y>0.0 ) p=vec2(p.x-k*p.y,-k*p.x-p.y)/2.0;
    p.x -= clamp( p.x, -2.0*r, 0.0 );
    return -length(p)*sign(p.y);
	}

	uniform vec2 u_resolution;
	uniform float u_time;

	void main () {
		//vec2 st = gl_FragCoord.xy / u_resolution.xy;
		vec2 st = gl_FragCoord.xy - u_resolution.xy*0.5;
    st /= u_resolution.y;

		//st -= 0.5;
		float circD = sdCircle(st, 0.4);
		float boxD = sdBox(st + vec2(1., 0.), vec2(0.4, 0.4));
		float triD = sdEquilateralTriangle(st + vec2(-1., 0.08), 0.4);
		float d = min(circD, boxD);
		d = min(d, triD);
		vec3 col = step(0.0, d) * (1. - vec3(d));
		gl_FragColor = vec4(col, 1.);
	}
`;

const flectFrag = `
	precision mediump float;
	uniform vec2 u_resolution;
	uniform sampler2D u_tex;
	uniform float u_noiseScale;

	float random (in vec2 _st) {
    return fract(sin(dot(_st.xy,
                         vec2(12.9898,78.233)))*
        43758.5453123);
	}

	void main () {
		vec2 st = gl_FragCoord.xy / u_resolution.xy;
		float r = (random(st) - 0.5) * (u_noiseScale / 100.);
		vec4 col = texture2D(u_tex, st + vec2(r, 0.));
		gl_FragColor = vec4(col.xyz, 1.);
	}
`

